const page = await browser.newPage({viewport:{width:1280,height:720}});
const errors=[]; page.on('pageerror', e=>errors.push(e.message)); page.on('console', m=>{if(m.type()==='error') errors.push(m.text())});
await page.route('**/src/main.js', route => route.fulfill({status:200, contentType:'text/javascript', body:instrumented}));
await page.goto('http://127.0.0.1:8765');
await page.locator('#start-btn').click();
const checks={start:await page.locator('#start').getAttribute('class')};
await page.evaluate(()=>{ for(const n of __test.npcs)n.group.position.set(1.7,0,1.7); __test.npcs[0].group.position.set(0,0,-0.62); });
await page.keyboard.press('KeyE'); await page.waitForTimeout(100);
checks.grab={state:await page.locator('#state-label').textContent(), npcState:await page.evaluate(()=>__test.heldNPC?.state)};
await page.evaluate(()=>{__test.yaw=Math.PI/2}); await page.waitForTimeout(100);
checks.facing=await page.evaluate(()=>({expected:__test.yaw, actual:__test.heldNPC?.group.rotation.y}));
await page.keyboard.press('KeyE'); await page.waitForTimeout(80);
checks.release=await page.evaluate(()=>({held:!!__test.heldNPC, npcState:__test.npcs[0].state}));
// Throw a deterministically positioned NPC.
await page.evaluate(()=>{ const n=__test.npcs[0]; n.group.position.set(0,0,-0.62); __test.yaw=0; }); await page.waitForTimeout(80);
await page.keyboard.press('KeyE'); await page.waitForTimeout(80); await page.keyboard.press('KeyF'); await page.waitForTimeout(80);
checks.throw=await page.evaluate(()=>({held:!!__test.heldNPC, state:__test.npcs[0].state}));
// Pick up and drop the closest weapon.
await page.evaluate(()=>{ for(const n of __test.npcs)n.group.position.set(1.7,0,1.7); const w=__test.weapons[0]; w.group.position.set(0,0,-0.65); __test.weapons[1].group.position.set(1.7,0,1.7); }); await page.waitForTimeout(80);
await page.keyboard.press('KeyE'); await page.waitForTimeout(80);
checks.pickup=await page.evaluate(()=>({held:__test.heldWeapon?.kind, weaponState:__test.weapons[0].state, label:document.querySelector('#state-label').textContent}));
await page.keyboard.press('KeyQ'); await page.waitForTimeout(80);
checks.drop=await page.evaluate(()=>({held:!!__test.heldWeapon, weaponState:__test.weapons[0].state, label:document.querySelector('#state-label').textContent}));
// Death screen and full respawn lifecycle.
await page.evaluate(()=>{__test.player.takeDamage(1000)}); await page.waitForTimeout(100);
checks.death=await page.locator('#death').getAttribute('class');
await page.locator('#respawn-btn').click(); await page.waitForTimeout(120);
checks.respawn=await page.evaluate(()=>({alive:__test.player.alive,hp:__test.player.health,npcs:__test.npcs.filter(n=>n.alive).length,deathClass:document.querySelector('#death').className}));
await page.screenshot({path:'/tmp/opencode/gorepit-check-latest.jpg',type:'jpeg',quality:65});
// Mobile: verify drop is present, visible, and grid doesn't collide with other actions.
const mobile=await browser.newPage({viewport:{width:390,height:844},isMobile:true,hasTouch:true});
await mobile.route('**/src/main.js', route => route.fulfill({status:200,contentType:'text/javascript',body:instrumented}));
await mobile.goto('http://127.0.0.1:8765'); await mobile.locator('#start-btn').click(); await mobile.waitForTimeout(100);
checks.mobile=await mobile.evaluate(()=>{const ids=['btn-spawn','btn-grab','btn-drop','btn-throw','btn-attack']; return {touch:document.body.classList.contains('touch'), display:getComputedStyle(document.querySelector('.touch-ui')).display, buttons:ids.map(id=>{const r=document.getElementById(id).getBoundingClientRect();return {id,x:Math.round(r.x),y:Math.round(r.y),w:Math.round(r.width),h:Math.round(r.height)}})}});
console.log(JSON.stringify({checks,errors},null,2));
await browser.close();
EOF

